 const closePanel=()=>{window.speechSynthesis?.cancel();setPanelClosing(true);window.setTimeout(()=>{setPanel(null);setPanelClosing(false)},150)}; useEffect(()=>{if(panel!=='ai')return;const onOutsidePointer=(event:PointerEvent)=>{const target=event.target;if(!(target instanceof Element))return;if(target.closest('.aiSide'))return;closePanel()};document.addEventListener('pointerdown',onOutsidePointer,true);return()=>document.removeEventListener('pointerdown',onOutsidePointer,true)},[panel]); const go=(r:string)=>{if((r==='#/admin'||r==='#/admin-statistics')&&!canAdmin)return;if(r==='#/admin-statistics'&&isBulkAdmin)r='#/admin';window.location.hash=r};
 const shareMaseNet=async()=>{const url=window.location.origin+'/';const data={title:'MaseNet | MaseMedia TV',text:'Discover MaseNet by MaseMedia TV.',url};try{const nav=navigator as Navigator&{share?:(data:{title:string;text:string;url:string})=>Promise<void>};if(nav.share){await nav.share(data);setShareFeedback('Share options opened.');}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);setShareFeedback('MaseNet link copied!');}else{const field=document.createElement('textarea');field.value=url;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();setShareFeedback(copied?'MaseNet link copied!':'Copy the site link from your browser address bar.');}}catch(e){if(e instanceof DOMException&&e.name==='AbortError'){setShareFeedback('Sharing cancelled.');}else{setShareFeedback('Could not share automatically. Copy the site link from your address bar.');}}window.setTimeout(()=>setShareFeedback(''),3500)};
  const filtered=useMemo(()=>{const normalizeSearch=(value:unknown)=>String(value??'').normalize('NFKC').toLocaleLowerCase().replace(/[’']/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim();const q=normalizeSearch(query);if(!q)return titles;const terms=q.split(/\s+/).filter(Boolean);const score=(t:Title)=>{const name=normalizeSearch(t.name);const episodeNames=normalizeSearch(t.episodes.map(e=>e.title).join(' '));const metadata=normalizeSearch([t.type,t.year,t.quality,...t.episodes.flatMap(e=>[`season ${e.season}`,`episode ${e.episode}`,e.quality,`s${e.season}e${e.episode}`])].join(' '));if(name===q)return 100;if(name.startsWith(q))return 80;if(name.includes(q))return 60;if(episodeNames.includes(q))return 50;if(terms.every(term=>name.includes(term)))return 45;if(metadata.includes(q)||terms.every(term=>metadata.includes(term)))return 30;return 0;return 0};return titles.map(title=>({title,score:score(title)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.title.name.localeCompare(b.title.name)).map(x=>x.title)},[titles,query]);
 const [telegramChannelResults,setTelegramChannelResults]=useState<{title:string;text:string;url:string;date?:string}[]>([]);
