 const lastNoResultSearch=useRef('');
 useEffect(()=>{const term=query.trim().replace(/\\s+/g,' ').slice(0,100);if(!searchOpen||term.length<3||filtered.length>0||lastNoResultSearch.current===term)return;lastNoResultSearch.current=term;fetch('/api/analytics',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({event:'search_no_results',itemName:term,itemId:'search-no-results'})}).catch(()=>{})},[query,searchOpen,filtered.length]);
 const episodeRouteParts=route.startsWith('#/episode/')?route.slice(10).split('/'):[];
