 async function googleLogin():Promise<boolean>{if(authBusy)return false;setAuthBusy(true);setAuthError('');try{const r=await auth.signIn();setViewer({...r.user,provider:'google'});return true}catch(e){const code=(e as {code?:string})?.code;if(code==='popup_blocked')setAuthError('Your browser blocked the Google sign-in window. Allow popups for MaseTv, then try again.');else if(code==='popup_closed')setAuthError('Google sign-in was cancelled. Tap Continue with Google to try again.');else if(code==='auth_error')setAuthError('Google authentication could not be completed. Please retry once or check that Google sign-in is allowed in your browser.');else setAuthError('MaseTv could not reach the Google sign-in service. Check your connection, then try again.');return false}finally{setAuthBusy(false)}}
 async function telegramLogin():Promise<boolean>{if(authBusy)return false;setAuthError('');if(!inTelegramMiniApp||!telegramWebApp?.initData){setAuthError('Open MaseNet from the Telegram Mini App, then tap Continue with Telegram to sign in securely.');return false}setAuthBusy(true);try{const r=await api.post('/api/telegram/enter',{initData:telegramWebApp.initData});if(r.data?.accessGranted&&r.data?.user){setViewer({...r.data.user,provider:'telegram'});setTelegramGate(null);setAuthError('')}else if(r.data?.accessGranted){setTelegramGate(null);setAuthError(r.data?.error||'Your access is approved, but Telegram sign-in could not be completed. Please retry.');return false}else{setTelegramGate({membership:r.data?.membership||{},membershipCheckErrors:r.data?.membershipCheckErrors||{},error:r.data?.error||'Complete the access steps below to enter MaseNet.'});return false}try{localStorage.setItem('masenet-liquid-onboarding-seen-v1','true')}catch{}setWelcomeOpen(false);return true}catch(e:any){setTelegramGate(null);setAuthError(e?.response?.data?.error||e?.message||'Telegram sign-in could not be completed. Please try again.');return false}finally{setAuthBusy(false)}}
