 const galleryPosterToDataUrl=async(file:File)=>{if(!file.type.startsWith('image/'))throw new Error('Choose an image from your Gallery.');if(file.size>30*1024*1024)throw new Error('This image is over 30MB. Please choose a smaller copy for reliable mobile upload.');const bitmap=await createImageBitmap(file);let scale=Math.min(1,640/bitmap.width,900/bitmap.height);let width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale));const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();throw new Error('Could not process this poster image.');}let data='';for(let attempt=0;attempt<8;attempt++){canvas.width=width;canvas.height=height;ctx.clearRect(0,0,width,height);ctx.drawImage(bitmap,0,0,width,height);const quality=attempt<4?Math.max(.42,.72-attempt*.1):.5;data=canvas.toDataURL('image/jpeg',quality);if(data.length<=350000)break;width=Math.max(240,Math.round(width*.82));height=Math.max(338,Math.round(height*.82));if(width===240&&height===338){canvas.width=width;canvas.height=height;ctx.drawImage(bitmap,0,0,width,height);data=canvas.toDataURL('image/jpeg',.42);break;}}bitmap.close();if(data.length>350000)throw new Error('This poster could not be compressed enough for upload. Try another image format.');return data;};
