  <div className="adminStats"><div className="adminStat"><span>All files</span><strong>{vaultAssets.length}</strong></div><div className="adminStat"><span>Awaiting review</span><strong>{vaultAssets.filter((a:any)=>a.status==='staged').length}</strong></div><div className="adminStat"><span>Approved / published</span><strong>{vaultAssets.filter((a:any)=>a.status==='published').length}</strong></div></div>
